use clap::{Parser, ValueDelimiter};
use chrono::Utc;
use std::io::{self, Read, Write};
use std::fs;
use std::path::Path;

#[derive(Parser, Debug)]
#[command(name = "executable")]
#[command(about = "CLI tool and library for saving web pages as a single HTML file", long_about = None)]
#[command(version = "2.11.0")]
struct Args {
    /// URL or file path, use - for STDIN
    #[arg(value_name = "TARGET")]
    target: String,

    /// Remove audio sources
    #[arg(short = 'a', long)]
    no_audio: bool,

    /// Set custom base URL
    #[arg(short = 'b', long, value_name = "http://localhost/")]
    base_url: Option<String>,

    /// Treat specified domains as blacklist
    #[arg(short = 'B', long)]
    blacklist_domains: bool,

    /// Remove CSS
    #[arg(short = 'c', long)]
    no_css: bool,

    /// Specify cookie file
    #[arg(short = 'C', long, value_name = "cookies.txt")]
    cookie_file: Option<String>,

    /// Specify domains to use for white/black-listing
    #[arg(short = 'd', long, value_name = "example.com", value_delimiter = ',')]
    domain: Vec<String>,

    /// Ignore network errors
    #[arg(short = 'e', long)]
    ignore_errors: bool,

    /// Enforce custom charset
    #[arg(short = 'E', long, value_name = "UTF-8")]
    encoding: Option<String>,

    /// Remove frames and iframes
    #[arg(short = 'f', long)]
    no_frames: bool,

    /// Remove fonts
    #[arg(short = 'F', long)]
    no_fonts: bool,

    /// Remove images
    #[arg(short = 'i', long)]
    no_images: bool,

    /// Cut off document from the Internet
    #[arg(short = 'I', long)]
    isolate: bool,

    /// Remove JavaScript
    #[arg(short = 'j', long)]
    no_js: bool,

    /// Allow invalid X.509 (TLS) certificates
    #[arg(short = 'k', long)]
    insecure: bool,

    /// Use MHTML as output format
    #[arg(short = 'm', long)]
    mhtml: bool,

    /// Exclude timestamp and source information
    #[arg(short = 'M', long)]
    no_metadata: bool,

    /// Replace NOSCRIPT elements with their contents
    #[arg(short = 'n', long)]
    unwrap_noscript: bool,

    /// File to write to, use - for STDOUT
    #[arg(short = 'o', long, value_name = "result.html")]
    output: Option<String>,

    /// Suppress verbosity
    #[arg(short = 'q', long)]
    quiet: bool,

    /// Adjust network request timeout
    #[arg(short = 't', long, value_name = "60")]
    timeout: Option<u64>,

    /// Set custom User-Agent string
    #[arg(short = 'u', long, value_name = "Firefox")]
    user_agent: Option<String>,

    /// Remove video sources
    #[arg(short = 'v', long)]
    no_video: bool,
}

fn main() {
    let args = Args::parse();

    // Read input
    let html_content = read_input(&args.target);

    // Process HTML
    let processed_html = process_html(&html_content, &args);

    // Write output
    if let Some(output_file) = &args.output {
        if output_file == "-" {
            print!("{}", processed_html);
        } else {
            fs::write(output_file, &processed_html).expect("Failed to write output file");
        }
    } else {
        print!("{}", processed_html);
    }
}

fn read_input(target: &str) -> String {
    if target == "-" {
        // Read from stdin
        let mut buffer = String::new();
        io::stdin()
            .read_to_string(&mut buffer)
            .expect("Failed to read from stdin");
        buffer
    } else if Path::new(target).exists() {
        // Read from file
        fs::read_to_string(target).expect("Failed to read file")
    } else {
        // For URLs, we would fetch them, but for now just treat as file
        fs::read_to_string(target).expect("Failed to read file")
    }
}

fn process_html(html: &str, args: &Args) -> String {
    let mut result = String::new();

    // Add metadata comment if not suppressed
    if !args.no_metadata {
        let now = Utc::now().format("%Y-%m-%dT%H:%M:%SZ");
        result.push_str(&format!(
            "<!-- Saved from local source at {} using monolith v2.11.0 -->\n",
            now
        ));
    }

    // Parse and process HTML
    let mut in_style = false;
    let mut in_noscript = false;
    let mut current_line = String::new();

    for ch in html.chars() {
        if ch == '\n' {
            process_line(&current_line, &mut result, args, &mut in_style, &mut in_noscript);
            current_line.clear();
        } else {
            current_line.push(ch);
        }
    }

    if !current_line.is_empty() {
        process_line(&current_line, &mut result, args, &mut in_style, &mut in_noscript);
    }

    result
}

fn process_line(
    line: &str,
    result: &mut String,
    args: &Args,
    in_style: &mut bool,
    in_noscript: &mut bool,
) {
    let trimmed = line.trim();

    // Check for style tag
    if trimmed.starts_with("<style") {
        *in_style = true;
    }
    if trimmed.contains("</style>") {
        *in_style = false;
    }

    // Check for noscript tag
    if trimmed.starts_with("<noscript") {
        *in_noscript = true;
        if args.unwrap_noscript {
            result.push_str("<!--noscript-->");
        } else {
            result.push_str(trimmed);
        }
        return;
    }
    if trimmed.starts_with("</noscript>") {
        *in_noscript = false;
        if args.unwrap_noscript {
            result.push_str("<!--/noscript-->\n");
        } else {
            result.push_str(trimmed);
        }
        return;
    }

    // Handle content inside noscript
    if *in_noscript && args.unwrap_noscript {
        if !trimmed.is_empty() && !trimmed.starts_with("<noscript") {
            result.push_str(trimmed);
        }
        return;
    }

    // Process line based on exclusion flags
    let processed = process_tag(line, args, *in_style);
    result.push_str(&processed);
}

fn process_tag(tag: &str, args: &Args, in_style: bool) -> String {
    let mut result = tag.to_string();

    // Remove CSS references if no_css
    if args.no_css {
        if tag.contains("<style") {
            // Clear style content
            if tag.contains("</style>") {
                result = tag.replace(
                    &tag[tag.find(">").unwrap() + 1..tag.rfind("</style>").unwrap()],
                    "",
                );
            }
        } else if tag.contains("rel=\"stylesheet\"") || tag.contains("rel='stylesheet'") {
            result = result.replace("href=", "");
            if let Some(start) = result.find("\"") {
                if let Some(end) = result[start + 1..].find("\"") {
                    result.replace_range(start..=start + end + 1, "");
                }
            }
        }
    }

    // Remove images if no_images
    if args.no_images {
        if tag.contains("<img") {
            result = result.replace("src=", "");
        }
    }

    // Remove JS if no_js
    if args.no_js {
        if tag.contains("<script") {
            // Clear script content
            if tag.contains("</script>") {
                result = tag.replace(
                    &tag[tag.find(">").unwrap() + 1..tag.rfind("</script>").unwrap()],
                    "",
                );
            } else {
                result = tag.replace("src=", "");
            }
        }
    }

    // Remove video if no_video
    if args.no_video {
        if tag.contains("<video") {
            result = result.replace("src=", "");
        }
    }

    // Remove audio if no_audio
    if args.no_audio {
        if tag.contains("<audio") {
            result = result.replace("src=", "");
        }
    }

    // Remove frames if no_frames
    if args.no_frames {
        if tag.contains("<iframe") {
            result = result.replace("src=", "");
        }
    }

    result
}
