fn process_line(line: &str, args: &Args, in_style: bool, in_script: bool) -> String {
    let mut result = line.to_string();

    // Handle CSS
    if args.no_css {
        if line.contains("<style") && line.contains("</style>") {
            // Single line style tag - empty it
            let start = line.find(">").unwrap() + 1;
            let end = line.rfind("</style>").unwrap();
            result = format!("{}>{}{}", &line[..start - 1], "", &line[end..]);
        } else if line.contains("<style") {
            // Multi-line style tag
            result = line.replace(">", ">\n").lines().next().unwrap_or(line).to_string();
        } else if in_style && !line.contains("</style>") {
            // Inside style tag - keep the line as is (we'll strip content elsewhere)
            result = line.to_string();
        } else if line.contains("rel=\"stylesheet\"") || line.contains("rel='stylesheet'") {
            // Link stylesheet - remove href
            result = remove_href(&line);
        }
    }

    // Handle images
    if args.no_images && line.contains("<img") {
        result = remove_src(&result);
    }

    // Handle JavaScript
    if args.no_js {
        if line.contains("<script") {
            if line.contains("</script>") {
                // Single line script tag - empty it
                let start = line.find(">").unwrap() + 1;
                let end = line.rfind("</script>").unwrap();
                result = format!("{}>{}{}", &line[..start - 1], "", &line[end..]);
            } else {
                // Multi-line script tag or start of script
                result = remove_src(&line);
            }
        }
    }

    // Handle video
    if args.no_video && line.contains("<video") {
        result = remove_src(&result);
    }

    // Handle audio
    if args.no_audio && line.contains("<audio") {
        result = remove_src(&result);
    }

    // Handle frames
    if args.no_frames && (line.contains("<iframe") || line.contains("<frame")) {
        result = remove_src(&result);
    }

    // Handle fonts
    if args.no_fonts && line.contains("@font-face") {
        // This is handled differently - we need to remove the src URL
        result = line.replace("url('", "url(").replace("url(\"", "url(").replace("')", ")").replace("\")", ")");
    }

    // Handle isolate mode - remove external URLs
    if args.isolate {
        // Remove src/href from external URLs (keep data: URLs)
        if line.contains("src=") && !line.contains("data:") {
            result = remove_src(&result);
        }
        if line.contains("href=") && !line.contains("data:") && !line.contains("#") {
            if !line.contains("rel=") || !line.contains("stylesheet") {
                result = remove_href(&result);
            }
        }
        // Remove font URLs
        if line.contains("url(") && line.contains("http") {
            result = result.replace("url('http", "url(").replace("url('https", "url(").replace("')", ")");
            result = result.replace("url(\"http", "url(").replace("url(\"https", "url(").replace("\")", ")");
            result = result.replace("url(http", "url(").replace("url(https", "url(");
        }
    }

    result
}

fn remove_src(line: &str) -> String {
    let re = Regex::new(r#"src\s*=\s*["']?[^"'\s>]*["']?"#).unwrap();
    re.replace_all(line, "src=").to_string()
}

fn remove_href(line: &str) -> String {
    let re = Regex::new(r#"href\s*=\s*["']?[^"'\s>]*["']?"#).unwrap();
    re.replace_all(line, "href=").to_string()
}
