    } else {
        fs::read_to_string(target).expect("Failed to read file")
    }
}

fn get_timestamp() -> String {
    match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(duration) => {
            let secs = duration.as_secs();
            let days_since_epoch = secs / 86400;
            let days_since_1970 = days_since_epoch;

            // Calculate date components from Unix epoch
            let mut year = 1970;
            let mut remaining_days = days_since_1970;

            loop {
                let days_in_year = if is_leap_year(year) { 366 } else { 365 };
                if remaining_days < days_in_year {
                    break;
                }
                remaining_days -= days_in_year;
                year += 1;
            }

            let month_days = if is_leap_year(year) {
                [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            } else {
                [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            };

            let mut month = 1;
            let mut day = remaining_days + 1;

            for m in 0..12 {
                if day <= month_days[m] {
                    month = m + 1;
                    break;
                }
                day -= month_days[m];
            }

            let secs_today = secs % 86400;
            let hours = secs_today / 3600;
            let minutes = (secs_today % 3600) / 60;
            let seconds = secs_today % 60;

            format!(
                "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
                year, month, day, hours, minutes, seconds
            )
        }
        Err(_) => "1970-01-01T00:00:00Z".to_string(),
    }
}

fn is_leap_year(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}

fn process_html(html: &str, args: &Args) -> String {
    let mut result = String::new();

    // Add metadata comment if not suppressed
    if !args.no_metadata {
        let timestamp = get_timestamp();
        result.push_str(&format!(
            "<!-- Saved from local source at {} using monolith v2.11.0 -->\n",
            timestamp
        ));
    }

    // Determine CSP policies to add
    let mut csp_parts = Vec::new();

    if args.no_css {
        csp_parts.push("style-src 'none'");
    }
    if args.no_js {
        csp_parts.push("script-src 'none'");
    }
    if args.no_frames {
        csp_parts.push("frame-src 'none'; child-src 'none'");
    }
    if args.no_fonts {
        csp_parts.push("font-src 'none'");
    }
    if args.no_images {
        csp_parts.push("img-src data:");
    }
    if args.isolate {
        csp_parts = vec!["default-src 'unsafe-eval' 'unsafe-inline' data:"];
    }

    // Process HTML
    process_html_content(html, args, &csp_parts, &mut result);

    result
}

fn process_html_content(html: &str, args: &Args, csp_parts: &[&str], result: &mut String) {
    let mut in_head = false;
    let mut head_processed = false;
    let mut in_style = false;
    let mut in_noscript = false;

    let lines: Vec<&str> = html.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];
        let trimmed = line.trim();

        // Track if we're in head
        if trimmed.contains("<head") && !trimmed.contains("</head") {
            in_head = true;
            result.push_str(line);
            result.push('\n');

            // Inject CSP meta tag right after <head
            if !head_processed && !csp_parts.is_empty() {
                let csp_value = if csp_parts.contains(&"default-src 'unsafe-eval' 'unsafe-inline' data:") {
                    "default-src 'unsafe-eval' 'unsafe-inline' data:"
                } else {
                    &csp_parts.join("; ")
                };
                result.push_str(&format!(
                    "<meta http-equiv=\"Content-Security-Policy\" content=\"{};\"></meta>\n",
                    csp_value
                ));
                head_processed = true;
            }
            i += 1;
            continue;
        }

        // Track style tags
        if trimmed.starts_with("<style") {
            in_style = true;
        }
        if trimmed.contains("</style>") {
            in_style = false;
        }

        // Handle noscript
        if trimmed.starts_with("<noscript") {
            in_noscript = true;
            if args.unwrap_noscript {
                result.push_str("<!--noscript-->");
            } else {
                result.push_str(line);
            }
            result.push('\n');
            i += 1;
            continue;
        }

        if trimmed.starts_with("</noscript>") {
            in_noscript = false;
            if args.unwrap_noscript {
                result.push_str("<!--/noscript-->\n");
            } else {
                result.push_str(line);
                result.push('\n');
            }
            i += 1;
            continue;
        }

        // Content inside noscript
        if in_noscript {
            if args.unwrap_noscript {
                result.push_str(line);
            } else {
                result.push_str(line);
            }
            result.push('\n');
            i += 1;
            continue;
        }

        // Process the line based on flags
        let processed = process_line(line, args, in_style);
        result.push_str(&processed);
        if !processed.ends_with('\n') {
            result.push('\n');
        }

        // Check if we're leaving head
        if trimmed.contains("</head>") {
            in_head = false;
        }

        i += 1;
    }
}

fn process_line(line: &str, args: &Args, in_style: bool) -> String {
    let mut result = line.to_string();

    // Handle CSS
    if args.no_css {
        if line.contains("<style") && line.contains("</style>") {
            // Single line style tag - empty it
            if let Some(start_idx) = result.find(">") {
                if let Some(end_idx) = result.rfind("</style>") {
                    let prefix = &result[..start_idx + 1];
                    let suffix = &result[end_idx..];
                    result = format!("{}{}", prefix, suffix);
                }
            }
        } else if line.contains("rel=\"stylesheet\"") || line.contains("rel='stylesheet'") {
            result = remove_attr(&result, "href");
        }
    }

    // Handle images
    if args.no_images && line.contains("<img") {
        result = remove_attr(&result, "src");
    }

    // Handle JavaScript
    if args.no_js {
        if line.contains("<script") && line.contains("</script>") {
            // Single line script tag - empty it
            if let Some(start_idx) = result.find(">") {
                if let Some(end_idx) = result.rfind("</script>") {
                    let prefix = &result[..start_idx + 1];
                    let suffix = &result[end_idx..];
                    result = format!("{}{}", prefix, suffix);
                }
            }
        } else if line.contains("<script") && !line.contains("</script>") {
            result = remove_attr(&result, "src");
        }
    }

    // Handle video
    if args.no_video && line.contains("<video") {
        result = remove_attr(&result, "src");
    }

    // Handle audio
    if args.no_audio && line.contains("<audio") {
        result = remove_attr(&result, "src");
    }

    // Handle frames
    if args.no_frames && (line.contains("<iframe") || line.contains("<frame")) {
        result = remove_attr(&result, "src");
    }

    // Handle fonts
    if args.no_fonts && line.contains("url(") {
        // Remove content inside url()
        while let Some(start) = result.find("url(") {
            if let Some(end) = result[start..].find(")") {
                result.replace_range(start + 4..start + end, "");
            } else {
                break;
            }
        }
    }

    // Handle isolate mode - remove external URLs
    if args.isolate {
        // Remove src attributes with external URLs
        if line.contains("src=") {
            let mut before_src = String::new();
            let mut after_src = String::new();
            let mut found = false;

            for part in result.split("src=") {
                if !found {
                    before_src.push_str(part);
                    found = true;
                } else {
                    // Keep data: URLs, remove http(s)://
                    if part.starts_with("data:") {
                        after_src.push_str("src=");
                        after_src.push_str(part);
                    } else if part.starts_with("'") || part.starts_with("\"") {
                        let quote = &part[0..1];
                        if let Some(end_quote) = part[1..].find(quote) {
                            let url = &part[1..end_quote + 1];
                            if !url.starts_with("http") && !url.starts_with("//") {
                                after_src.push_str("src=");
                                after_src.push_str(&part[..end_quote + 2]);
                                after_src.push_str(&part[end_quote + 2..]);
                            } else {
                                after_src.push_str(&part[end_quote + 2..]);
                            }
                        } else {
                            after_src.push_str(part);
                        }
                    }
                }
            }
            if found && !after_src.is_empty() {
                result = format!("{}{}", before_src, after_src);
            }
        }

        // Remove font URLs
        if line.contains("url(") && (line.contains("http://") || line.contains("https://")) {
            result = result.replace("url('http", "url(").replace("url('https", "url(");
            result = result.replace("url(\"http", "url(").replace("url(\"https", "url(");
            result = result.replace("')", ")").replace("\")", ")");
        }
    }

    result
}

fn remove_attr(line: &str, attr_name: &str) -> String {
    let mut result = String::new();
    let attr_pattern_double = format!("{}=\"", attr_name);
    let attr_pattern_single = format!("{}='", attr_name);
    let attr_pattern_no_quote = format!("{}=", attr_name);

    let mut remaining = line;

    loop {
        if let Some(pos_double) = remaining.find(&attr_pattern_double) {
            result.push_str(&remaining[..pos_double]);
            remaining = &remaining[pos_double + attr_pattern_double.len()..];

            if let Some(quote_end) = remaining.find('"') {
                remaining = &remaining[quote_end + 1..];
            } else {
                break;
            }
        } else if let Some(pos_single) = remaining.find(&attr_pattern_single) {
            result.push_str(&remaining[..pos_single]);
            remaining = &remaining[pos_single + attr_pattern_single.len()..];

            if let Some(quote_end) = remaining.find('\'') {
                remaining = &remaining[quote_end + 1..];
            } else {
                break;
            }
        } else {
            result.push_str(remaining);
            break;
        }
    }

    result
}
