fn read_input(target: &str) -> String {
    if target == "-" {
        let mut buffer = String::new();
        io::stdin()
            .read_to_string(&mut buffer)
            .expect("Failed to read from stdin");
        buffer
    } else if Path::new(target).exists() {
        fs::read_to_string(target).expect("Failed to read file")
    } else {
        fs::read_to_string(target).expect("Failed to read file")
    }
}

fn get_timestamp() -> String {
    match SystemTime::now().duration_since(UNIX_EPOCH) {
        Ok(duration) => {
            let secs = duration.as_secs();
            let days_since_epoch = secs / 86400;

            let mut year = 1970;
            let mut remaining_days = days_since_epoch;

            loop {
                let days_in_year = if is_leap_year(year) { 366 } else { 365 };
                if remaining_days < days_in_year {
                    break;
                }
                remaining_days -= days_in_year;
                year += 1;
            }

            let month_days = if is_leap_year(year) {
                [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            } else {
                [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31]
            };

            let mut month = 1;
            let mut day = remaining_days + 1;

            for m in 0..12 {
                if day <= month_days[m] {
                    month = m + 1;
                    break;
                }
                day -= month_days[m];
            }

            let secs_today = secs % 86400;
            let hours = secs_today / 3600;
            let minutes = (secs_today % 3600) / 60;
            let seconds = secs_today % 60;

            format!(
                "{:04}-{:02}-{:02}T{:02}:{:02}:{:02}Z",
                year, month, day, hours, minutes, seconds
            )
        }
        Err(_) => "1970-01-01T00:00:00Z".to_string(),
    }
}

fn is_leap_year(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}

fn process_html(html: &str, args: &Args) -> String {
    let mut result = String::new();

    // Add metadata comment if not suppressed
    if !args.no_metadata {
        let timestamp = get_timestamp();
        result.push_str(&format!(
            "<!-- Saved from local source at {} using monolith v2.11.0 -->\n",
            timestamp
        ));
    }

    // Determine CSP policies to add
    let mut csp_parts = Vec::new();

    if args.no_css {
        csp_parts.push("style-src 'none'");
    }
    if args.no_js {
        csp_parts.push("script-src 'none'");
    }
    if args.no_frames {
        csp_parts.push("frame-src 'none'; child-src 'none'");
    }
    if args.no_fonts {
        csp_parts.push("font-src 'none'");
    }
    if args.no_images {
        csp_parts.push("img-src data:");
    }
    if args.isolate {
        csp_parts = vec!["default-src 'unsafe-eval' 'unsafe-inline' data:"];
    }

    // Process HTML
    process_html_content(html, args, &csp_parts, &mut result);

    result
}

fn process_html_content(html: &str, args: &Args, csp_parts: &[&str], result: &mut String) {
    let mut in_head = false;
    let mut head_end_found = false;
    let mut in_noscript = false;

    let mut i = 0;
    let html_chars: Vec<char> = html.chars().collect();

    while i < html_chars.len() {
        // Look for tag starts
        if html_chars[i] == '<' {
            // Find the end of the tag
            let mut tag_end = i + 1;
            let mut tag_content = String::new();

            while tag_end < html_chars.len() && html_chars[tag_end] != '>' {
                tag_content.push(html_chars[tag_end]);
                tag_end += 1;
            }

            if tag_end < html_chars.len() {
                let full_tag = format!("<{}>", tag_content);
                let tag_lower = full_tag.to_lowercase();

                // Track head
                if tag_lower.starts_with("<head") && !tag_lower.contains("</head") {
                    in_head = true;
                    result.push_str(&full_tag);
                    i = tag_end + 1;

                    // Skip whitespace/newlines after head tag
                    while i < html_chars.len() && (html_chars[i] == '\n' || html_chars[i] == '\r' || html_chars[i] == ' ' || html_chars[i] == '\t') {
                        i += 1;
                    }

                    // Inject CSP and robots meta if in head
                    if !csp_parts.is_empty() && !head_end_found {
                        let csp_value = if csp_parts.contains(&"default-src 'unsafe-eval' 'unsafe-inline' data:") {
                            "default-src 'unsafe-eval' 'unsafe-inline' data:"
                        } else {
                            &csp_parts.join("; ")
                        };
                        result.push('\n');
                        result.push_str(&format!(
                            "<meta http-equiv=\"Content-Security-Policy\" content=\"{};\"></meta>",
                            csp_value
                        ));
                    }

                    // Add robots meta
                    if !head_end_found {
                        result.push('\n');
                        result.push_str("<meta name=\"robots\" content=\"none\"></meta>");
                    }
                    head_end_found = true;

                    continue;
                }

                if tag_lower.starts_with("</head>") {
                    in_head = false;
                }

                // Handle noscript
                if tag_lower.starts_with("<noscript") {
                    in_noscript = true;
                    if !args.unwrap_noscript {
                        result.push_str(&full_tag);
                    } else {
                        result.push_str("<!--noscript-->");
                    }
                    i = tag_end + 1;
                    continue;
                }

                if tag_lower.starts_with("</noscript>") {
                    in_noscript = false;
                    if !args.unwrap_noscript {
                        result.push_str(&full_tag);
                    } else {
                        result.push_str("<!--/noscript-->");
                    }
                    i = tag_end + 1;
                    continue;
                }

                // Process the tag
                let processed_tag = process_tag(&full_tag, args);
                result.push_str(&processed_tag);
                i = tag_end + 1;
            } else {
                result.push(html_chars[i]);
                i += 1;
            }
        } else {
            // Handle text content (newlines are sometimes preserved in certain contexts)
            if html_chars[i] == '\n' && in_noscript && args.unwrap_noscript {
                // Skip newlines in unwrapped noscript
                i += 1;
            } else if in_noscript && args.unwrap_noscript && (html_chars[i] == ' ' || html_chars[i] == '\t') {
                // Skip leading whitespace in unwrapped noscript
                i += 1;
            } else {
                result.push(html_chars[i]);
                i += 1;
            }
        }
    }
}

fn process_tag(tag: &str, args: &Args) -> String {
    let tag_lower = tag.to_lowercase();
    let mut result = tag.to_string();

    // Handle CSS
    if args.no_css {
        if tag_lower.contains("<style") && tag_lower.contains("</style>") {
            // Empty style content
            if let Some(start_idx) = result.find(">") {
                if let Some(end_idx) = result.rfind("</style>") {
                    result = format!("{}{}", &result[..start_idx + 1], &result[end_idx..]);
                }
            }
        } else if tag_lower.contains("rel=\"stylesheet\"") || tag_lower.contains("rel='stylesheet'") {
            result = remove_attr(&result, "href");
        }
    }

    // Handle images
    if args.no_images && tag_lower.contains("<img") {
        result = remove_attr(&result, "src");
    }

    // Handle JavaScript
    if args.no_js {
        if tag_lower.contains("<script") && tag_lower.contains("</script>") {
            // Empty script content
            if let Some(start_idx) = result.find(">") {
                if let Some(end_idx) = result.rfind("</script>") {
                    result = format!("{}{}", &result[..start_idx + 1], &result[end_idx..]);
                }
            }
        } else if tag_lower.contains("<script") && !tag_lower.contains("</script>") {
            result = remove_attr(&result, "src");
        }
    }

    // Handle video
    if args.no_video && tag_lower.contains("<video") {
        result = remove_attr(&result, "src");
    }

    // Handle audio
    if args.no_audio && tag_lower.contains("<audio") {
        result = remove_attr(&result, "src");
    }

    // Handle frames
    if args.no_frames && (tag_lower.contains("<iframe") || tag_lower.contains("<frame")) {
        result = remove_attr(&result, "src");
    }

    // Handle fonts
    if args.no_fonts && tag_lower.contains("url(") {
        // Remove content inside url()
        while let Some(start) = result.find("url(") {
            if let Some(end) = result[start..].find(")") {
                result.replace_range(start + 4..start + end, "");
            } else {
                break;
            }
        }
    }

    // Handle isolate mode
    if args.isolate {
        if tag_lower.contains("src=") && !tag_lower.contains("data:") {
            result = remove_attr(&result, "src");
        }
        if tag_lower.contains("href=") && !tag_lower.contains("data:") {
            result = remove_attr(&result, "href");
        }
        if tag_lower.contains("url(") && (tag_lower.contains("http://") || tag_lower.contains("https://")) {
            while let Some(start) = result.find("url(") {
                if let Some(end) = result[start..].find(")") {
                    result.replace_range(start + 4..start + end, "");
                } else {
                    break;
                }
            }
        }
    }

    result
}

fn remove_attr(tag: &str, attr_name: &str) -> String {
    let mut result = String::new();
    let attr_pattern_double = format!("{}=\"", attr_name);
    let attr_pattern_single = format!("{}='", attr_name);

    let mut remaining = tag;

    loop {
        if let Some(pos_double) = remaining.find(&attr_pattern_double) {
            result.push_str(&remaining[..pos_double]);
            remaining = &remaining[pos_double + attr_pattern_double.len()..];

            if let Some(quote_end) = remaining.find('"') {
                remaining = &remaining[quote_end + 1..];
            } else {
                break;
            }
        } else if let Some(pos_single) = remaining.find(&attr_pattern_single) {
            result.push_str(&remaining[..pos_single]);
            remaining = &remaining[pos_single + attr_pattern_single.len()..];

            if let Some(quote_end) = remaining.find('\'') {
                remaining = &remaining[quote_end + 1..];
            } else {
                break;
            }
        } else {
            result.push_str(remaining);
            break;
        }
    }

    result
}
