    // First pass: remove style/script content and collect HTML
    let mut cleaned = String::new();
    let mut i = 0;
    let chars: Vec<char> = html.chars().collect();

    while i < chars.len() {
        if chars[i] == '<' {
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '>' {
                j += 1;
            }

            if j < chars.len() {
                let tag_str: String = chars[i + 1..j].iter().collect();
                let tag_lower = tag_str.to_lowercase();

                // Handle style tags
                if args.no_css && tag_lower.starts_with("style") && !tag_lower.contains("/style") {
                    cleaned.push_str("<style>");
                    i = j + 1;

                    // Skip content until </style>
                    while i < chars.len() {
                        if i + 7 < chars.len() {
                            let closing: String = chars[i..].iter().take(8).collect();
                            if closing == "</style>" {
                                cleaned.push_str("</style>");
                                i += 8;
                                break;
                            }
                        }
                        i += 1;
                    }
                    continue;
                }

                // Handle script tags
                if args.no_js && tag_lower.starts_with("script") && !tag_lower.contains("/script") && !tag_lower.contains("src=") {
                    cleaned.push_str("<script>");
                    i = j + 1;

                    // Skip content until </script>
                    while i < chars.len() {
                        if i + 8 < chars.len() {
                            let closing: String = chars[i..].iter().take(9).collect();
                            if closing == "</script>" {
                                cleaned.push_str("</script>");
                                i += 9;
                                break;
                            }
                        }
                        i += 1;
                    }
                    continue;
                }

                cleaned.push('<');
                cleaned.push_str(&tag_str);
                cleaned.push('>');
                i = j + 1;
            } else {
                cleaned.push(chars[i]);
                i += 1;
            }
        } else {
            cleaned.push(chars[i]);
            i += 1;
        }
    }

    // Second pass: process tags and add metas
    let mut head_close_pos = None;
    if let Some(pos) = cleaned.find("</head>") {
        head_close_pos = Some(pos);
    }

    if let Some(pos) = head_close_pos {
        let before_head_close = &cleaned[..pos];
        let after_head_close = &cleaned[pos..];

        // Process first part
        let mut processed_part = process_content(before_head_close, args);

        // Add meta tags before </head>
        if need_csp {
            processed_part.push('\n');
            processed_part.push_str(&format!(
                "<meta http-equiv=\"Content-Security-Policy\" content=\"{};\"></meta>",
                csp_value
            ));
        }
        processed_part.push_str("\n<meta name=\"robots\" content=\"none\"></meta>");

        // Process rest
        let mut processed_rest = process_content(after_head_close, args);

        result.push_str(&processed_part);
        result.push_str(&processed_rest);
    } else {
        // No head close, just process normally
        let processed = process_content(&cleaned, args);
        result.push_str(&processed);
    }

    result
}

fn process_content(html: &str, args: &Args) -> String {
    let mut result = String::new();
    let mut in_noscript = false;

    let mut i = 0;
    let chars: Vec<char> = html.chars().collect();

    while i < chars.len() {
        if chars[i] == '<' {
            let mut j = i + 1;
            while j < chars.len() && chars[j] != '>' {
                j += 1;
            }

            if j < chars.len() {
                let tag_str: String = chars[i + 1..j].iter().collect();
                let tag_lower = tag_str.to_lowercase();

                if tag_lower.starts_with("noscript") && !tag_lower.contains("/noscript") {
                    in_noscript = true;
                    if args.unwrap_noscript {
                        result.push_str("<!--noscript-->");
                    } else {
                        result.push('<');
                        result.push_str(&tag_str);
                        result.push('>');
                    }
                    i = j + 1;
                    continue;
                }

                if tag_lower.starts_with("/noscript") {
                    in_noscript = false;
                    if args.unwrap_noscript {
                        result.push_str("<!--/noscript-->");
                    } else {
                        result.push('<');
                        result.push_str(&tag_str);
                        result.push('>');
                    }
                    i = j + 1;
                    continue;
                }

                let processed = process_tag(&tag_str, args);
                result.push('<');
                result.push_str(&processed);
                result.push('>');
                i = j + 1;
            } else {
                result.push(chars[i]);
                i += 1;
            }
        } else {
            if in_noscript && args.unwrap_noscript {
                if chars[i] != '\n' && chars[i] != '\t' && chars[i] != ' ' || (i + 1 < chars.len() && chars[i + 1] != '<') {
                    result.push(chars[i]);
                }
            } else {
                result.push(chars[i]);
            }
            i += 1;
        }
    }

    result
}

fn process_tag(tag: &str, args: &Args) -> String {
    let tag_lower = tag.to_lowercase();
    let mut result = tag.to_string();

    // Handle CSS
    if args.no_css {
        if (tag_lower.contains("rel=\"stylesheet\"") || tag_lower.contains("rel='stylesheet'")) && tag_lower.contains("href=") {
            result = remove_attr(&result, "href");
        }
    }

    // Handle images
    if args.no_images && tag_lower.contains("img") && tag_lower.contains("src=") {
        result = remove_attr(&result, "src");
    }

    // Handle JavaScript
    if args.no_js {
        if tag_lower.contains("script") && tag_lower.contains("src=") && !tag_lower.contains("</script") {
            result = remove_attr(&result, "src");
        }
    }

    // Handle video
    if args.no_video && tag_lower.contains("video") && tag_lower.contains("src=") {
        result = remove_attr(&result, "src");
    }

    // Handle audio
    if args.no_audio && tag_lower.contains("audio") && tag_lower.contains("src=") {
        result = remove_attr(&result, "src");
    }

    // Handle frames
    if args.no_frames && (tag_lower.contains("iframe") || tag_lower.contains("frame")) && tag_lower.contains("src=") {
        result = remove_attr(&result, "src");
    }

    // Handle fonts
    if args.no_fonts && tag_lower.contains("url(") {
        while let Some(start) = result.find("url(") {
            if let Some(end) = result[start..].find(")") {
                result.replace_range(start + 4..start + end, "");
            } else {
                break;
            }
        }
    }

    // Handle isolate mode
    if args.isolate {
        if tag_lower.contains("src=") && !tag_lower.contains("data:") {
            result = remove_attr(&result, "src");
        }
        if tag_lower.contains("href=") && !tag_lower.contains("data:") && !tag_lower.contains("#") {
            result = remove_attr(&result, "href");
        }
        if tag_lower.contains("url(") && (tag_lower.contains("http://") || tag_lower.contains("https://")) {
            while let Some(start) = result.find("url(") {
                if let Some(end) = result[start..].find(")") {
                    result.replace_range(start + 4..start + end, "");
                } else {
                    break;
                }
            }
        }
    }

    result
}

fn remove_attr(tag: &str, attr_name: &str) -> String {
    let mut result = String::new();
    let attr_pattern_double = format!("{}=\"", attr_name);
    let attr_pattern_single = format!("{}='", attr_name);

    let mut remaining = tag;

    loop {
        if let Some(pos_double) = remaining.find(&attr_pattern_double) {
            result.push_str(&remaining[..pos_double]);
            remaining = &remaining[pos_double + attr_pattern_double.len()..];

            if let Some(quote_end) = remaining.find('"') {
                remaining = &remaining[quote_end + 1..];
            } else {
                break;
            }
        } else if let Some(pos_single) = remaining.find(&attr_pattern_single) {
            result.push_str(&remaining[..pos_single]);
            remaining = &remaining[pos_single + attr_pattern_single.len()..];

            if let Some(quote_end) = remaining.find('\'') {
                remaining = &remaining[quote_end + 1..];
            } else {
                break;
            }
        } else {
            result.push_str(remaining);
            break;
        }
    }

    result
}
